from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class UserCreate(BaseModel):
    username: str = Field(..., min_length=3)
    email: str
    password: str

@app.post("/users/")
def create_user(user: UserCreate):
    return {"username": user.username, "email": user.email}
